const $=s=>document.querySelector(s), fmt=(v,d=0)=>Number(v).toLocaleString('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={growth:3,importPressure:2,risk:1,capacity:70000,domestic:76,lme:2900,premium:155,fx:84,freight:35,depot:1200,duty:0,auction:160,partner:'In-house',po:false,commercial:false};
let settings={...defaults},customers=[{name:'Customer A',sector:'Galvanization',metal:'Zinc',demand:18000,hzl:11000},{name:'Customer B',sector:'Infrastructure',metal:'Zinc',demand:12000,hzl:9000},{name:'Customer C',sector:'Automotive',metal:'Zinc',demand:10000,hzl:6500},{name:'Customer D',sector:'Steel',metal:'Zinc',demand:16000,hzl:12000},{name:'Customer E',sector:'Battery / automotive',metal:'Lead',demand:9000,hzl:5000},{name:'Customer F',sector:'Industrial batteries',metal:'Lead',demand:5000,hzl:3500}];
try{settings={...defaults,...JSON.parse(localStorage.getItem('hzl-settings')||'{}')};customers=JSON.parse(localStorage.getItem('hzl-customers')||'null')||customers}catch{}
const pages=[['overview','◈','Market overview'],['forecast','⌁','Demand & order book'],['shipments','⇄','Import & shipment radar'],['pricing','◇','Premium & pricing'],['customers','◎','Customer demand'],['exports','↗','Markets & allocation'],['sources','▦','Data & implementation']];
let current='overview';const metal=()=>$('#metal').value, months=()=>$('#horizon').value==='quarter'?['Jan 2027','Feb 2027','Mar 2027']:['Nov 2026','Dec 2026','Jan 2027'];
const customerRows=()=>customers.filter(c=>c.metal===metal());
function model(){const rows=customerRows(),base=rows.reduce((a,c)=>a+c.hzl,0);const rate=(+settings.growth-+settings.importPressure*.35-+settings.risk*.4)/100;const forecast=months().map((m,i)=>{const offset=($('#horizon').value==='quarter'?3:1)+i;const point=Math.round(base*Math.pow(1+rate,offset));const width=.12+.03*offset;return {month:m,point,low:Math.round(point*(1-width)),high:Math.round(point*(1+width)),booked:Math.round(base*[.64,.42,.24][i])}});return {base,forecast,total:forecast.reduce((a,r)=>a+r.point,0),demand:rows.reduce((a,c)=>a+c.demand,0)}}
function save(){localStorage.setItem('hzl-settings',JSON.stringify(settings));localStorage.setItem('hzl-customers',JSON.stringify(customers))}
function card(title,sub,body,tag=''){return `<section class="card"><div class="card-head"><div><h2>${title}</h2><p>${sub}</p></div>${tag?`<span class="tag">${tag}</span>`:''}</div>${body}</section>`}
function kpi(label,value,unit,hint){return `<div class="kpi"><div class="kpi-label">${label}</div><div class="value">${value} <span class="unit">${unit}</span></div><div class="hint">${hint}</div></div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function chart(){const {base,forecast}=model(),vals=[base*.9,base*.96,base, ...forecast.map(f=>f.point)],max=Math.max(...forecast.map(f=>f.high))*1.12;const x=i=>55+i*94,y=v=>210-v/max*175;const points=vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ');const band=forecast.map((f,i)=>`${x(i+3)},${y(f.high)}`).concat([...forecast].reverse().map((f,j)=>`${x(5-j)},${y(f.low)}`)).join(' ');return `<svg class="chart" viewBox="0 0 570 258" role="img" aria-label="Illustrative monthly order book, history and forecast range in tonnes">${[0,.25,.5,.75,1].map(v=>`<line x1="48" y1="${210-v*175}" x2="550" y2="${210-v*175}" stroke="#edf1eb"/><text x="2" y="${214-v*175}">${fmt(max*v/1000,0)}k</text>`).join('')}<line x1="290" x2="290" y1="20" y2="214" stroke="#d4ddce" stroke-dasharray="4 4"/><text x="303" y="19">SCENARIO →</text><polygon points="${band}" fill="#dce9d0" opacity=".8"/><polyline points="${points.split(' ').slice(0,3).join(' ')}" fill="none" stroke="#267451" stroke-width="3"/><polyline points="${points.split(' ').slice(2).join(' ')}" fill="none" stroke="#267451" stroke-width="3" stroke-dasharray="6 4"/>${vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="white" stroke="#267451" stroke-width="2"/>`).join('')}${['Aug*','Sep*','Oct*',...months().map(m=>m.slice(0,3))].map((m,i)=>`<text x="${x(i)-10}" y="238">${m}</text>`).join('')}</svg><div class="legend"><span><i class="key"></i>Sample history*</span><span><i class="key pale"></i>Scenario sensitivity range</span></div><p class="mini">*Schematic sample history; not observed HZL orders. Range is not a statistical confidence interval.</p>`}
function split(){const domestic=+settings.domestic,cap=capacity();return `<div class="splitbar"><div style="width:${domestic}%"></div><div style="width:${100-domestic}%"></div></div><div class="split-labels"><span>Domestic <strong>${domestic}%</strong><br>${fmt(cap*domestic/100)} t / month</span><span>Export <strong>${100-domestic}%</strong><br>${fmt(cap*(100-domestic)/100)} t / month</span></div>`}
function capacity(){return +settings.capacity*(metal()==='Lead'?.28:1)}
function overview(){const m=model(),sw=m.demand?100*m.base/m.demand:0;return `<div class="kpis">${kpi('3-month order-book scenario',fmt(m.total/1000,1),'kt','Customer-weighted planning estimate')}${kpi('First forecast month · '+months()[0],fmt(m.forecast[0].point/1000,1),'kt','Demand drivers & import sensitivity')}${kpi('Customer share of wallet',fmt(sw,1),'%','HZL tonnes ÷ total customer demand')}${kpi('Forecast confidence','Unvalidated','','Target above 90% · definition pending')}</div><div class="grid">${card('A forward view of the order book','Monthly volume · '+metal()+' · tonnes',chart(), '3-month outlook')}${card('Domestic & export allocation','Editable planning split · '+metal(),split()+`<p style="margin-top:28px">${fmt(capacity())} t monthly planning capacity</p><button class="link" data-page="exports">Explore allocation →</button>`)}</div><div class="notice"><span>↗</span><div><strong>Bring shipment signals ahead of reported trade data</strong><p>Korea / Japan reporting carries an approximately one-month lag per the meeting. Vessel ETAs and shipment milestones are required to bridge that gap. No live feeds are connected.</p></div></div><div class="grid equal">${card('Demand signals to watch','Planning inputs from the client discussion',bars())}${card('Commercial watchlist','Illustrative monitoring rules; no current market claims',`<div class="signal"><span class="signal-icon">⇄</span><div><strong>Import arrivals & global metal movement</strong><p>Track origin, destination, volume, ETA confidence and duplicate shipments.</p></div></div><div class="signal"><span class="signal-icon">◇</span><div><strong>Quarterly premium discovery</strong><p>Combine import parity, previous auction clears and competitor offers.</p></div></div><div class="signal"><span class="signal-icon">!</span><div><strong>Geopolitical & market exposure</strong><p>Test freight disruption, FX movements and steel-sector slowdowns.</p></div></div>`)}</div>`}
function bars(){const rows=metal()==='Zinc'?[['Galvanization',43],['Infrastructure',27],['Automotive',18],['Steel & other',12]]:[['Automotive battery',64],['Industrial battery',36]];return rows.map(([n,v])=>`<div class="bar-row"><span>${n}</span><div class="track"><div class="fill" style="width:${v}%"></div></div><span>${v}%</span></div>`).join('')+'<p class="mini">Illustrative driver weights; validate sector exposure with the client.</p>'}
function field(key,label,step=1){return `<div class="field"><label for="${key}">${label}</label><input id="${key}" data-setting="${key}" type="number" step="${step}" value="${settings[key]}" ${['growth','importPressure'].includes(key)?'min="-30" max="30"':'min="0"'}></div>`}
function forecast(){const m=model();return `<div class="notice"><div><strong>The above-90% preference needs an agreed success measure</strong><p>Confidence-interval coverage and forecast accuracy are different. Agree a volume-error tolerance and rolling monthly backtests at 1-, 2- and 3-month horizons. This prototype has no trained model or measured accuracy.</p></div></div><div class="grid">${card('Monthly order-book scenario','Visible range reflects assumed sensitivity, not probability',chart())}${card('Scenario controls','Changes apply to both the forecast and overview',`<div class="form-grid" style="grid-template-columns:1fr">${field('growth','Monthly demand growth (%)',.1)}${field('importPressure','Import pressure index (−30 to 30)',.1)}${field('risk','Market / geopolitical risk index (0–10)',.1)}</div><button data-action="recalc">Apply scenario</button><button class="secondary" data-action="reset-scenario">Reset</button>`)}</div>${card('Three-month planning book','All volumes illustrative · tonnes',table(['Month','Booked sample','Total expected','Unbooked opportunity','Sensitivity range'],m.forecast.map(r=>[r.month,fmt(r.booked),fmt(r.point),fmt(Math.max(0,r.point-r.booked)),`${fmt(r.low)}–${fmt(r.high)}`])))}${card('Model foundation & candidate inputs','Specification for a production forecasting pipeline',`<ul class="metric-list"><li><strong>Target:</strong> customer × metal × month order tonnes; separately predict total customer demand and HZL share of wallet.</li><li><strong>Inputs:</strong> lagged orders, bookings, cancellations, customer total demand, HZL wallet share, inventories, imports and vessel ETAs; galvanization, infrastructure, automotive and steel indicators; LME, FX, premiums, freight and depot cost; country balances and dated event signals.</li><li><strong>Baseline:</strong> seasonal naive and customer run rate; compare candidate statistical / ML models with rolling-origin backtests. Use only information available at each forecast cutoff to prevent leakage.</li><li><strong>Premium history:</strong> collect bid and clearing premium, auction date, grade, location, volume, delivery terms, currency, LME reference and losing/no-bid auctions. Missing historical premium data blocks reliable calibration.</li><li><strong>Prototype formula:</strong> monthly HZL customer volume × (1 + growth − 0.35 × import pressure − 0.4 × risk)<sup>months ahead</sup>. Percent inputs are divided by 100. Sensitivity width = ±(12% + 3% × months ahead). Coefficients are demonstration assumptions.</li></ul><button class="link" data-action="method">View validation checklist →</button>`)}`}
const shipments=[['SAMPLE-ZN-01','Zinc','South Korea','India · West coast',6400,'04 Nov 2026','Estimated','Customs sample · lagged'],['SAMPLE-ZN-02','Zinc','Japan','India · West coast',4200,'12 Nov 2026','Unconfirmed','Booking sample'],['SAMPLE-ZN-03','Zinc','Australia','India · East coast',5100,'21 Nov 2026','Estimated','Carrier sample'],['SAMPLE-PB-01','Lead','South Korea','India · West coast',2100,'08 Nov 2026','Estimated','Booking sample'],['SAMPLE-PB-02','Lead','Japan','India · East coast',1500,'19 Nov 2026','Unconfirmed','Carrier sample']];
function shipmentView(){const rows=shipments.filter(r=>r[1]===metal());return `<div class="kpis">${kpi('Sample inbound pipeline',fmt(rows.reduce((a,r)=>a+r[4],0)/1000,1),'kt','Selected metal · illustrative records')}${kpi('Tracked sample shipments',rows.length,'','No AIS or carrier connection')}${kpi('Korea / Japan trade lag','~1','month','Meeting-stated limitation')}${kpi('Real-time feed status','Not connected','','Predictive arrival engine pending')}</div>${card('Import & shipment radar','Global origin → India · no live tracking implied',table(['Shipment','Origin','Destination','Tonnes','ETA','Status'],rows.map(r=>[`<button class="link" data-shipment="${r[0]}">${r[0]}</button>`,r[2],r[3],fmt(r[4]),r[5],`<span class="tag ${r[6]==='Unconfirmed'?'amber':'gray'}">${r[6]}</span>`])))}<div class="grid equal">${card('From fragmented sources to arrival intelligence','Required ingestion and reconciliation',`<div class="steps"><div class="step"><strong>Collect shipment events</strong><p>Licensed vessel/AIS data, bills of lading, bookings, port calls and carrier milestones.</p></div><div class="step"><strong>Resolve metal & route</strong><p>Match grade, HS code, cargo quantity, origin and destination; distinguish zinc/lead cargo from unrelated vessel movements.</p></div><div class="step"><strong>Predict and reconcile arrivals</strong><p>ETA distributions, port congestion and quantity uncertainty; deduplicate by shipment identity before monthly aggregation.</p></div></div>`) }${card('Movement & market outlook','Requirements from the meeting',`<ul class="metric-list"><li>Track country-level production, consumption, imports and exports with consistent metal, product form and units.</li><li>Compare reported trade with estimated arrivals; retain publication date and revision history.</li><li>Flag geopolitical events, sanctions or freight disruptions as dated signals needing verification.</li><li>Use ILZSG and Wood Mackenzie as structural context; cadence and licensing must be checked before operational use.</li></ul>`)}</div>`}
function pricing(){const usd=+settings.lme + +settings.premium + +settings.freight,landed=usd*+settings.fx*(1+ +settings.duty/100)+ +settings.depot;return `<div class="notice"><div><strong>Import-parity pricing → informed auction starting premium</strong><p>The meeting describes HZL's import-parity approach and quarterly auction discovery. This calculator is an editable illustration; validate duty, tax treatment, delivery basis and HZL's approved commercial formula.</p></div></div>${card('Import-parity workbench','Inputs are assumptions, not current market quotes',`<div class="form-grid">${field('lme','LME reference (USD/t)')}${field('premium','Import premium (USD/t)')}${field('fx','FX (INR per USD)',.01)}${field('freight','Incremental freight / insurance (USD/t)')}${field('depot','Depot / inland cost (INR/t)')}${field('duty','Illustrative duty (%)',.1)}</div><button data-action="recalc">Recalculate parity</button><div class="result flex"><div><span class="muted">Indicative landed import parity</span><div class="value">₹${fmt(landed)} <span class="unit">/ t</span></div></div><span class="tag amber">Scenario only</span></div><p class="mini">(LME + import premium + incremental freight) × FX × (1 + duty %) + depot cost. Avoid adding freight already embedded in the premium. Simplified duty base; GST and other taxes excluded.</p>`)}<div class="grid equal">${card('Quarterly auction starting premium','Human-reviewed commercial input',`${field('auction','Proposed auction starting premium (USD/t)')}<div class="result"><span class="muted">Gap to sample import premium</span><div class="value">${+settings.auction-+settings.premium>=0?'+':''}${fmt(+settings.auction-+settings.premium)} <span class="unit">USD/t</span></div></div><button data-action="recalc">Save planning assumption</button><p class="mini">Starting premium is an input, not a recommendation. Auction clearing remains the discovery mechanism.</p>`)}${card('Premium direction & benchmarking','Evidence required before issuing a recommendation',`<ul class="metric-list"><li><strong>Direction:</strong> unavailable until premium history, bids, imports and inventory are connected.</li><li><strong>Benchmark HZL vs global players:</strong> normalize grade, date, geography, Incoterm, credit and volume. Compare realized premium, landed cost, lead time and reliability.</li><li><strong>Inputs needed:</strong> quarterly auction clears, current competitor offers, regional premiums, LME, FX and logistics history.</li><li><strong>Decision:</strong> review comparable landed offers and demand scenarios to set a starting premium before the auction.</li></ul>`)}</div>`}
function customerView(){const m=model();return `<div class="kpis">${kpi('Monthly customer demand',fmt(m.demand/1000,1),'kt','Selected sample customers')}${kpi('Monthly HZL volume',fmt(m.base/1000,1),'kt','Selected sample customers')}${kpi('Share of wallet',fmt(m.demand?m.base/m.demand*100:0,1),'%','Weighted by customer demand')}${kpi('Addressable wallet gap',fmt((m.demand-m.base)/1000,1),'kt','Total demand less HZL volume')}</div>${card('Customer demand & wallet','Sample customer names; no client data has been loaded',table(['Customer','Sector','Total demand (t/month)','HZL (t/month)','Wallet share',''],customerRows().map(c=>[esc(c.name),esc(c.sector),fmt(c.demand),fmt(c.hzl),fmt(c.demand?100*c.hzl/c.demand:0,1)+'%',`<button class="link" data-customer="${customers.indexOf(c)}">Edit</button>`])))}${card('Add a planning customer','Saved only in this browser; do not enter sensitive production data',`<form id="customer-form"><div class="form-grid"><div class="field"><label for="cname">Customer name</label><input id="cname" required maxlength="80"></div><div class="field"><label for="csector">Sector</label><select id="csector"><option>Galvanization</option><option>Infrastructure</option><option>Automotive</option><option>Steel</option><option>Battery / automotive</option><option>Other</option></select></div><div class="field"><label for="cdemand">Total monthly demand (t)</label><input id="cdemand" type="number" min="0" required></div><div class="field"><label for="chzl">Monthly HZL volume (t)</label><input id="chzl" type="number" min="0" required></div></div><button>Add ${metal()} customer</button><p id="customer-error" role="alert"></p></form>`)} `}
const countries=[['Vietnam',190,135,65,10,65],['Bangladesh',110,15,100,5,80],['Thailand',175,90,100,15,70],['Indonesia',230,180,75,25,75]];
function exportView(){const cap=capacity(),dom=cap*settings.domestic/100,scale=metal()==='Lead'?.5:1;return `${card('Domestic versus export planning','Allocation reconciles to available monthly capacity',`<div class="form-grid">${field('capacity','Zinc monthly capacity (t); Lead = 28%')}<div class="field"><label for="domestic">Domestic allocation: <span id="split-value">${settings.domestic}</span>%</label><input id="domestic" data-setting="domestic" type="range" min="0" max="100" value="${settings.domestic}"></div></div><button data-action="recalc">Apply allocation</button>${split()}<p class="mini">Capacity assumptions are illustrative. Domestic plan ${fmt(dom)} t; first forecast month order scenario ${fmt(model().forecast[0].point)} t. ${dom<model().forecast[0].point?'Domestic plan falls below expected order scenario; review allocation.':'Domestic plan covers expected order scenario; validate actual commitments.'}</p>`)}${card('Potential export-market screening','Illustrative country balances · annual kt · selected metal',table(['Market','Consumption','Production','Imports','Exports','Net import need','Screening'],countries.map(r=>{const c=r[1]*scale,p=r[2]*scale,i=r[3]*scale,e=r[4]*scale;return [r[0],fmt(c,1),fmt(p,1),fmt(i,1),fmt(e,1),fmt(i-e,1),`<button class="link" data-country="${r[0]}">Review →</button>`]}))+`<p class="mini">Sample production + imports − exports = consumption, with zero stock change assumed. Gross trade can coexist with production. Import need alone does not establish accessible HZL opportunity.</p>`)}<div class="grid equal">${card('Market selection checks','Requirements before prioritizing exports',`<ul class="metric-list"><li>Country consumption, production, net imports and inventory changes on the same product basis.</li><li>Tariffs, trade restrictions, product certification, customer access and credit risk.</li><li>Export premium less freight, depot and handling costs on a comparable delivery basis.</li><li>Global-player benchmarks and route reliability alongside domestic opportunity cost.</li></ul>`)}${card('Commercial netback comparison','A consistent basis is required',`<div class="empty">No validated domestic or export offers connected.</div><p class="mini">Connect normalized customer offers and route costs to calculate export netback and optimize domestic/export allocation subject to commitments and capacity.</p>`)}</div>`}
function sourceView(){return `<div class="notice"><div><strong>Build the foundation before connecting production data</strong><p>The supplied meeting transcript excerpt and earlier summary have been reviewed. The excerpt omits 2:21–15:14; no production dataset was supplied. Existing operating records remain synthetic unless a trained model is explicitly selected.</p></div></div>${card('Source register & freshness','A single registry for fragmented import intelligence',table(['Source','Purpose','Freshness / limitation','Connection'],[['Legacy import supplier','Former import intelligence','Client-reported contact channels unavailable; validate replacement sources independently','<span class="tag amber">Replacement needed</span>'],['Korea / Japan trade data','Reported bilateral imports','~1-month lag per meeting; revisions possible','Not connected'],['ILZSG','Metal balances / structural context','Cadence, granularity and release lag require verification','Not connected'],['Fastmarkets','Metal pricing / movement reports','Licensed feed option; confirm cadence and use rights','Not connected'],['Wood Mackenzie','Market outlook / supply-demand context','Licensed access, forecast horizon and update cadence require verification','Not connected'],['AIS / carrier / port / cargo feeds','Predictive shipment arrivals','Provider coverage, metal attribution and latency must be validated','Not connected'],['HZL ERP / CRM / auctions','Orders, customer wallet and premiums','Customer demand and lost bids may require new collection','Not connected'],['LME / FX / freight / depot','Comparable parity / netback','Licensed feeds, timestamps and delivery basis required','Not connected']]))}<div class="grid equal">${card('Delivery model & partner onboarding','Planning checklist · stored in this browser',`<div class="field"><label for="partner">Implementation route</label><select id="partner" data-setting="partner"><option ${settings.partner==='In-house'?'selected':''}>In-house</option><option ${settings.partner==='Third-party partner'?'selected':''}>Third-party partner</option></select></div><p style="margin-top:20px"><label><input id="commercial" data-setting="commercial" type="checkbox" ${settings.commercial?'checked':''}> Commercial onboarding completed</label></p><p><label><input id="po" data-setting="po" type="checkbox" ${settings.po?'checked':''}> Relevant PO arrangements completed</label></p><button data-action="recalc">Save checklist</button><div class="result">${settings.partner==='In-house'?'In-house route selected. Assign data, platform and forecasting owners.':settings.po&&settings.commercial?'Checklist marked complete. Confirm approved scope and secure access before partner data transfer.':'Customer-data handoff pending commercial onboarding and relevant PO arrangements.'}</div><p class="mini">This checklist does not transfer data, onboard a vendor or issue a PO.</p>`)}${card('Phased implementation','From this prototype to an operational system',`<div class="steps"><div class="step"><strong>Data foundation</strong><p>Confirm vendor history, owners, access rights, common metal/customer IDs, history and freshness service levels.</p></div><div class="step"><strong>Pilot forecasts & parity</strong><p>Connect ERP, auctions and initial shipment feeds. Backtest seasonal baselines before ML; normalize prices and delivery terms.</p></div><div class="step"><strong>Predictive operations</strong><p>Train calibrated arrival and demand models; validate the three monthly horizons and confidence objective.</p></div><div class="step"><strong>Controlled rollout</strong><p>SSO, role-based access, audit logs, monitoring and partner access after onboarding. Add persistent server storage and scheduled ingestion.</p></div></div>`)}</div>${card('Open questions from the client discussion','Resolve these before committing accuracy or delivery timelines',`<ul class="metric-list"><li>Confirm replacement import sources and independently verify vendor identity and current availability.</li><li>Does above 90% mean accuracy within a defined volume tolerance, prediction interval coverage, or another measure?</li><li>How much monthly customer demand, HZL sales, lost orders and historical auction premium data is available?</li><li>Which metal grades, depots, country coverage and shipping routes are in scope?</li><li>What is HZL's approved import-parity formula and tax / freight / Incoterm treatment?</li><li>Which sources can be licensed and who will own in-house or third-party delivery?</li></ul><div class="download"><button data-action="download-spec">Download implementation brief</button><button class="secondary" data-action="reset-all">Reset browser sample data</button></div>`)}`}
function render(){current=location.hash.slice(1)||'overview';if(!pages.some(p=>p[0]===current))current='overview';const p=pages.find(p=>p[0]===current);$('#nav').innerHTML=pages.map(p=>`<a href="#${p[0]}" class="${p[0]===current?'active':''}"><span>${p[1]}</span>${p[2]}</a>`).join('');$('#title').textContent=p[2];$('#crumb').textContent='Commercial intelligence / '+p[2];$('#subtitle').textContent={overview:'Demand, shipments and pricing. One connected view.',forecast:'A monthly planning view for the next three months or next quarter.',shipments:'Connect lagged reported trade with forward shipment signals.',pricing:'Explore landed parity and prepare for quarterly premium discovery.',customers:'Understand total demand, HZL volume and the available wallet.',exports:'Screen export opportunities and balance available metal.',sources:'Sources, open questions and the path to a production application.'}[current];$('#view').innerHTML=({overview,forecast,shipments:shipmentView,pricing,customers:customerView,exports:exportView,sources:sourceView})[current]();bind()}
function modal(title,html){$('#detail-title').textContent=title;$('#detail-body').innerHTML=html;$('#detail').showModal()}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function apply(){for(const el of document.querySelectorAll('[data-setting]')){const key=el.dataset.setting;if(el.type==='checkbox')settings[key]=el.checked;else if(el.type==='number'||el.type==='range'){if(!el.checkValidity()||!Number.isFinite(+el.value)){el.reportValidity();return false}settings[key]=+el.value}else settings[key]=el.value}if(settings.risk>10){modal('Check risk input','<p>Risk index must be between 0 and 10.</p>');return false}save();render();return true}
function bind(){document.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>location.hash=e.dataset.page);document.querySelectorAll('[data-shipment]').forEach(e=>e.onclick=()=>{const r=shipments.find(r=>r[0]===e.dataset.shipment);modal(r[0],`<p><strong>${esc(r[2])} → ${esc(r[3])}</strong></p><p>${fmt(r[4])} t ${r[1]}; sample ETA ${r[5]}.</p><p>Evidence: ${r[7]}. ETA confidence has not been estimated. No vessel identification or live tracking is attached.</p><p>Production drill-down should show event timestamps, vessel/cargo linkage, quantity revisions, deduplication keys and provider provenance.</p>`)});document.querySelectorAll('[data-country]').forEach(e=>e.onclick=()=>modal(e.dataset.country+' · market screening',`<p>Synthetic country balance only; the displayed volumes are not verified market data.</p><p>Collect monthly product-level consumption, production, imports, exports and stock changes, then check tariff access, realized premiums, customer fit and route cost before assigning HZL export volume.</p>`));document.querySelectorAll('[data-customer]').forEach(e=>e.onclick=()=>{const i=+e.dataset.customer,c=customers[i];modal('Edit '+c.name,`<form id="edit-form"><div class="form-grid"><div class="field"><label for="edit-demand">Total demand (t/month)</label><input id="edit-demand" type="number" min="0" value="${c.demand}" required></div><div class="field"><label for="edit-hzl">HZL volume (t/month)</label><input id="edit-hzl" type="number" min="0" value="${c.hzl}" required></div></div><p id="edit-error" role="alert"></p><button>Save customer</button></form>`);$('#edit-form').onsubmit=ev=>{ev.preventDefault();const d=+$('#edit-demand').value,h=+$('#edit-hzl').value;if(h>d){$('#edit-error').textContent='HZL volume cannot exceed total customer demand.';return}c.demand=d;c.hzl=h;save();$('#detail').close();render()}});document.querySelectorAll('[data-action]').forEach(e=>e.onclick=()=>action(e.dataset.action));if($('#domestic'))$('#domestic').oninput=e=>$('#split-value').textContent=e.target.value;if($('#customer-form'))$('#customer-form').onsubmit=e=>{e.preventDefault();const d=+$('#cdemand').value,h=+$('#chzl').value;if(h>d){$('#customer-error').textContent='HZL volume cannot exceed total customer demand.';return}customers.push({name:$('#cname').value.trim()||'Unnamed',sector:$('#csector').value,metal:metal(),demand:d,hzl:h});save();render()}}
function action(a){if(a==='recalc')apply();if(a==='reset-scenario'){settings.growth=3;settings.importPressure=2;settings.risk=1;save();render()}if(a==='method')modal('Forecast acceptance checklist','<p>Agree the target, tolerance and definition of confidence. Track WAPE and signed bias at each monthly horizon, using customer and metal segmentation. Handle zero-demand customers separately.</p><p>Compare rolling-origin test forecasts against seasonal naive baselines using publication-date snapshots. Fit intervals only from held-out residuals; measure interval coverage, width and drift. A 90% coverage interval does not mean 90% point accuracy.</p><p>Document data completeness, late arrivals, revisions, model version and overrides. No accuracy or confidence result is available in this prototype.</p>');if(a==='download-spec')download('HZL-implementation-brief.md',spec());if(a==='reset-all')modal('Reset sample data','<p>This removes planning edits saved in this browser and restores the initial sample records.</p><button id="confirm-reset">Reset sample data</button>');if(a==='reset-all')$('#confirm-reset').onclick=()=>{localStorage.removeItem('hzl-settings');localStorage.removeItem('hzl-customers');location.reload()}}
function spec(){return `# HZL Metal Intelligence — implementation brief\n\nScope: supplied meeting transcript excerpt and earlier requirements summary. The excerpt skips 2:21 to 15:14. No production dataset supplied. All prototype numbers are synthetic.\n\n## Decisions\n- Monthly order-book forecast: next 3 months and next calendar quarter, by metal/customer.\n- Predictive imports and shipments bridging approximately one-month Korea/Japan trade reporting lag.\n- Customer demand and weighted HZL share of wallet.\n- Quarterly auction starting premium informed by import parity and comparable market intelligence.\n- Domestic/export allocation and country market screening.\n\n## Sources\nERP/CRM/orders, customer demand, auction bids/clears, LME, FX, depot/freight, licensed cargo/AIS/carrier feeds, Korea/Japan trade, ILZSG, Fastmarkets and Wood Mackenzie. Confirm rights, cadence and limits. Legacy-supplier replacement is required; the private transcript review records the meeting-reported name and contact issues without treating them as independently verified current facts.\n\n## Data model\ncustomer_demand(customer_id, metal, grade, month, total_tonnes, hzl_tonnes, known_at)\norders(order_id, customer_id, metal, grade, delivery_month, booked_tonnes, status, known_at)\nshipments(shipment_id, metal, hs_code, origin, destination, tonnes, eta, event_at, known_at, provider)\nprices(metal, grade, location, incoterm, date, lme_usd_t, premium_usd_t, fx, freight, depot, known_at)\nauctions(auction_id, date, grade, depot, volume_t, starting_premium, clearing_premium, currency, terms)\ncountry_balance(country, metal, product_form, period, production, consumption, imports, exports, stock_change, published_at)\nforecasts(model_version, cutoff_at, target_month, customer_id, metal, point_tonnes, lower, upper, interval_level)\n\n## Modeling\nStart with customer run-rate and seasonal-naive baselines. Use lagged orders, imports, ETAs, sector indicators, metal prices, premiums, forex, route costs and geopolitical events available at prediction time. Rolling-origin backtests at 1, 2 and 3 months; WAPE, bias and calibrated interval coverage. The requested above-90% target must be defined with the client; no guarantee is made.\n\n## Pricing\nValidate import-parity formula and duty/tax base with HZL. Normalize global-player prices by grade, date, location, volume, delivery terms and credit. Avoid double-counting freight. Human-reviewed auction starting premium, not automatic clearing-price replacement.\n\n## Architecture\nLicensed batch/stream connectors -> immutable source landing -> validation and entity resolution -> governed warehouse -> feature pipeline -> forecast services -> authenticated API -> integrated dashboard. Add SSO, scoped roles, encryption, audit logs, data freshness monitoring, model drift alerts, persistent storage and scheduled ingestion. Browser-only prototype storage is not production infrastructure.\n\n## Delivery\n1. Confirm requirements, vendor history, commercial formula, source access and data contracts.\n2. Ingest history and reconcile orders, customers, auctions and metal movement.\n3. Pilot forecast and premium workbench; validate vs baselines on held-out months.\n4. Add predictive shipments, country screening and constrained allocation.\n5. Controlled production rollout with monitoring.\n\n## Partner pathway\nSelect in-house or third-party delivery. Share customer data only after the relevant commercial onboarding and PO arrangements and approved secure access scope. The prototype transfers no data.\n`}
$('#metal').onchange=render;$('#horizon').onchange=render;$('#close').onclick=()=>$('#detail').close();window.onhashchange=render;
$('#export').onclick=()=>{const rows=model().forecast;const metadata=`Classification,Illustrative sample data\nMetal,${metal()}\nView,${pages.find(p=>p[0]===current)[2]}\nReference date,2026-10-23\n`;let csv;if(current==='customers')csv='Customer,Sector,Total demand t per month,HZL t per month,Share of wallet pct\n'+customerRows().map(c=>[c.name,c.sector,c.demand,c.hzl,c.demand?100*c.hzl/c.demand:0].map(csvCell).join(',')).join('\n');else if(current==='shipments')csv='Shipment,Metal,Origin,Destination,Tonnes,Sample ETA,Status,Source\n'+shipments.filter(r=>r[1]===metal()).map(r=>r.map(csvCell).join(',')).join('\n');else if(current==='pricing'){const landed=(+settings.lme + +settings.premium + +settings.freight)*settings.fx*(1+settings.duty/100)+ +settings.depot;csv='LME USD per t,Import premium USD per t,FX INR per USD,Freight USD per t,Depot INR per t,Duty pct,Landed parity INR per t,Auction start USD per t\n'+[settings.lme,settings.premium,settings.fx,settings.freight,settings.depot,settings.duty,landed,settings.auction].join(',')}else if(current==='sources'){download('HZL-implementation-brief.md',spec());return}else if(current==='exports')csv='Market,Consumption kt,Production kt,Imports kt,Exports kt,Net imports kt\n'+countries.map(r=>[r[0],...r.slice(1,5).map(v=>v*(metal()==='Lead'?.5:1)),(r[3]-r[4])*(metal()==='Lead'?.5:1)].join(',')).join('\n')+`\n\nAllocation,Monthly tonnes\nDomestic,${capacity()*settings.domestic/100}\nExport,${capacity()*(100-settings.domestic)/100}`;else csv='Month,Booked sample t,Expected t,Sensitivity low t,Sensitivity high t\n'+rows.map(r=>[r.month,r.booked,r.point,r.low,r.high].join(',')).join('\n');download('HZL-'+current+'-'+metal()+'.csv',metadata+'\n'+csv,'text/csv;charset=utf-8')};
function csvCell(v){let s=String(v);if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}render();
